CREATE TABLE IF NOT EXISTS catering_packages (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), provider_id varchar NOT NULL REFERENCES users(id) ON DELETE CASCADE, title varchar(120) NOT NULL, description text NOT NULL, category varchar(40) NOT NULL, cover_image text, gallery_images jsonb NOT NULL DEFAULT '[]'::jsonb, pricing_model varchar(30) NOT NULL, starting_price numeric(12,2) NOT NULL, currency varchar(3) NOT NULL DEFAULT 'USD', minimum_guests integer NOT NULL, maximum_guests integer, preparation_style varchar(100), service_style varchar(100), cuisines jsonb NOT NULL DEFAULT '[]'::jsonb, dietary_accommodations jsonb NOT NULL DEFAULT '[]'::jsonb, included_services jsonb NOT NULL DEFAULT '[]'::jsonb, optional_add_ons jsonb NOT NULL DEFAULT '[]'::jsonb, estimated_duration integer, active boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, display_order integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), CONSTRAINT catering_packages_price_check CHECK (starting_price >= 0), CONSTRAINT catering_packages_guests_check CHECK (minimum_guests > 0 AND (maximum_guests IS NULL OR maximum_guests >= minimum_guests)));
CREATE INDEX IF NOT EXISTS catering_packages_provider_order_idx ON catering_packages(provider_id, display_order, created_at);
ALTER TABLE catering_inquiries ADD COLUMN IF NOT EXISTS package_id varchar REFERENCES catering_packages(id) ON DELETE SET NULL;
